// Valida el evento que envía la API después de la reserva en P02 (HU0003-1.0) y del registro de la asistencia en G04
// (HU0004-1.0 «Asistió - Interesado» y HU0004-2.0 «No asistió»), según ADR-16 «Receptor agendamiento»: el cuerpo es
// exactamente { id_cita } con un entero de 1 a 2147483647. Cualquier otro campo lo invalida: el contrato lleva solo
// identificadores (C10, C11). La salida lleva solo { valido, id_cita } (A3, D3).
const esObjeto = (valor) => valor !== null && typeof valor === 'object' && !Array.isArray(valor);

return $input.all().map((item, indice) => {
  const cuerpo = esObjeto(item.json?.body) ? item.json.body : null;
  const claves = cuerpo ? Object.keys(cuerpo) : [];
  const id = cuerpo?.id_cita;
  const valido = claves.length === 1 && claves[0] === 'id_cita' && Number.isSafeInteger(id) && id > 0 && id <= 2147483647;
  return { json: { valido, id_cita: valido ? id : null }, pairedItem: { item: indice } };
});

// Barrido de agendamiento (ADR-16, S12): un ítem por cada cita de GET /internal/agendamiento/pendientes (avisos del
// estado actual de la cita sin notificación con más de 1 min, y avisos cuyo último intento lleva más de 10 min
// pendiente). Recupera la confirmación (HU0003-1.0), las credenciales (HU0004-1.0) y la invitación a reprogramar
// (HU0004-2.0) cuando el evento del webhook no llegó o el intento quedó pendiente. Si no hay pendientes no sale ningún
// ítem y la ejecución termina aquí. Solo lleva id_cita (A3).
const salida = [];
$input.all().forEach((item, indice) => {
  const citas = Array.isArray(item.json?.citas) ? item.json.citas : [];
  for (const c of citas) {
    if (Number.isSafeInteger(c?.id_cita) && c.id_cita > 0 && c.id_cita <= 2147483647) {
      salida.push({ json: { id_cita: c.id_cita }, pairedItem: { item: indice } });
    }
  }
});
return salida;

// Decide qué hace agendamiento con lo que devolvió notificacion-multicanal para cada aviso de la visita: la
// confirmación (HU0003-1.0), las credenciales del portal (HU0004-1.0, D3) y la invitación a reprogramar (HU0004-2.0).
// Sigue ADR-07 «Fallos de los avisos de la visita»: la clasificación de D7, sin rebote ni transición (P-j).
// Entrada: un ítem por aviso, emparejado con su reserva de la salida «reservado» de «¿Reserva hecha?» por el pairedItem
// que pone Execute Workflow (el subflujo corre una vez por ítem); si falta, por la posición. Es el resultado del
// subflujo, { id_expediente, correo: { estado_envio, id_notificacion }, whatsapp }, o, si falló, { error: "<mensaje>" }
// (Execute Workflow con onError continueRegularOutput, C9).
//   enviado   <- correo.estado_envio = enviado: el subflujo ya cerró la fila                    -> termina
//   fallido   <- correo.estado_envio = fallido: rechazo permanente del destinatario; con la fila reservada el subflujo
//                no la cierra                      (motivo rechazo_destinatario) -> PATCH fallido y termina sin error
//             <- error «notificacion-multicanal: entrada inválida…» (400): un defecto, la entrada la arma la API
//                                                  (motivo entrada_invalida)     -> PATCH fallido y Stop and Error
//   pendiente <- correo.estado_envio = pendiente (error técnico de SMTP, o un 5xx que no es rechazo permanente), un 502,
//                un 500 o cualquier otro error: resultado desconocido (R22), nunca se marca fallido
//                                                  -> sin PATCH y Stop and Error; el barrido lo retoma a los 10 min
//                                                     con un intento nuevo (una fila por intento, ADR-07)
// Lo que no se reconoce cae en pendiente.
// A3 (D3): la salida lleva solo la acción, el motivo y los ids de la cita, el expediente y la notificación. Nunca el
// asunto ni el cuerpo de la reserva, ni el mensaje del error del subflujo. El cuerpo de las credenciales trae la contraseña temporal.
const ENTRADA_INVALIDA = 'notificacion-multicanal: entrada inválida';
const reservas = $('¿Reserva hecha?').all(0);

const clasificar = (resultado) => {
  if (resultado.error !== undefined) {
    const mensaje = typeof resultado.error === 'string' ? resultado.error : String(resultado.error?.message ?? '');
    return mensaje.startsWith(ENTRADA_INVALIDA)
      ? { accion: 'fallido', motivo: 'entrada_invalida' }
      : { accion: 'pendiente', motivo: 'notificacion_no_disponible' };
  }
  switch (resultado.correo?.estado_envio) {
    case 'enviado':
      return { accion: 'enviado', motivo: 'enviado' };
    case 'fallido':
      return { accion: 'fallido', motivo: 'rechazo_destinatario' };
    case 'pendiente':
      return { accion: 'pendiente', motivo: 'smtp_pendiente' };
    default:
      return { accion: 'pendiente', motivo: 'resultado_desconocido' };
  }
};

return $input.all().map((item, indice) => {
  const reserva = reservas[item.pairedItem?.item ?? indice]?.json?.body ?? {};
  return {
    json: {
      ...clasificar(item.json ?? {}),
      id_cita: reserva.id_cita ?? null,
      id_expediente: reserva.id_expediente ?? null,
      id_notificacion: reserva.id_notificacion ?? null,
    },
    pairedItem: { item: indice },
  };
});

// Valida el evento que envía la API después de «Confirmar citas» y de cada aviso de reprogramación (HU0009-1.0 y HU0009-2.0),
// según ADR-16: el cuerpo es exactamente { id_expediente, id_notificacion } con enteros de 1 a 2147483647. Cualquier otro
// campo lo invalida: el contrato lleva solo identificadores (C10, C11). La salida lleva solo
// { valido, id_expediente, id_notificacion, tipo_evento } (tipo_evento es null: el webhook trae la fila ya reservada).
const esObjeto = (valor) => valor !== null && typeof valor === 'object' && !Array.isArray(valor);
const entero = (n) => Number.isSafeInteger(n) && n > 0 && n <= 2147483647;

return $input.all().map((item, indice) => {
  const cuerpo = esObjeto(item.json?.body) ? item.json.body : null;
  const claves = cuerpo ? Object.keys(cuerpo).sort() : [];
  const valido = claves.length === 2 && claves[0] === 'id_expediente' && claves[1] === 'id_notificacion' && entero(cuerpo.id_expediente) && entero(cuerpo.id_notificacion);
  return {
    json: { valido, id_expediente: valido ? cuerpo.id_expediente : null, id_notificacion: valido ? cuerpo.id_notificacion : null, tipo_evento: null },
    pairedItem: { item: indice },
  };
});

// Barrido de la rama evaluaciones de agendamiento (ADR-16, C27; HU0009, HU0010, HU0025 y HU0012-HU0015): un ítem por cada aviso de
// GET /internal/evaluaciones/avisos-pendientes ({ id_expediente, tipo_evento }: avisos sin fila de notificación o con el último
// intento pendiente hace más de 10 min). Sin id_notificacion: la API retoma con una fila nueva o cierra por tope (ADR-07).
// Si no hay pendientes no sale ningún ítem y la ejecución termina aquí. Solo lleva identificadores y el tipo de aviso.
const TIPOS = ['evaluaciones_habilitadas', 'evaluaciones_confirmadas', 'evaluacion_reprogramada', 'evaluacion_reprogramada_responsable', 'evaluacion_liberada_responsable', 'evaluacion_inasistencia', 'dictamen_en_observacion', 'dictamen_no_apto', 'vacante_asignada', 'lista_espera', 'cuota_por_conciliar'];
const salida = [];
$input.all().forEach((item, indice) => {
  const avisos = Array.isArray(item.json?.avisos) ? item.json.avisos : [];
  for (const a of avisos) {
    if (Number.isSafeInteger(a?.id_expediente) && a.id_expediente > 0 && a.id_expediente <= 2147483647 && TIPOS.includes(a?.tipo_evento)) {
      salida.push({ json: { id_expediente: a.id_expediente, id_notificacion: null, tipo_evento: a.tipo_evento }, pairedItem: { item: indice } });
    }
  }
});
return salida;

// Decide qué hace la rama evaluaciones de agendamiento con lo que devolvió notificacion-multicanal para los avisos de
// evaluación (HU0009-1.0 y HU0009-2.0). Sigue ADR-07 «Fallos de los avisos» (clasificación de D7, sin
// rebote ni transición).
// Entrada: un ítem por aviso, emparejado con su reserva (salida «reservado» de «Según la reserva de evaluación») por el pairedItem que pone
// Execute Workflow; si falta, por la posición. Es el resultado del subflujo, { id_expediente, correo: { estado_envio,
// id_notificacion }, whatsapp }, o, si falló, { error: "<mensaje>" } (Execute Workflow con onError continueRegularOutput, C9).
//   enviado   <- correo.estado_envio = enviado: el subflujo ya cerró la fila                    -> termina
//   fallido   <- correo.estado_envio = fallido: rechazo permanente del destinatario (motivo rechazo_destinatario)
//                                                                                              -> PATCH fallido, sin error
//             <- error «notificacion-multicanal: entrada inválida…» (400): un defecto (motivo entrada_invalida)
//                                                                                              -> PATCH fallido y registro del fallo
//   pendiente <- correo.estado_envio = pendiente, un 502, un 500 o cualquier otro error: resultado desconocido (R22), nunca
//                se marca fallido -> sin PATCH y registro del fallo; el barrido lo retoma a los 10 min con un intento nuevo
// Lo que no se reconoce cae en pendiente.
// La salida lleva solo la acción, el motivo y los ids del expediente y la notificación. Nunca el asunto ni el cuerpo del
// aviso, ni el mensaje del error del subflujo (C11).
const ENTRADA_INVALIDA = 'notificacion-multicanal: entrada inválida';
const reservas = $('Según la reserva de evaluación').all(0);

const clasificar = (resultado) => {
  if (resultado.error !== undefined) {
    const mensaje = typeof resultado.error === 'string' ? resultado.error : String(resultado.error?.message ?? '');
    return mensaje.startsWith(ENTRADA_INVALIDA)
      ? { accion: 'fallido', motivo: 'entrada_invalida' }
      : { accion: 'pendiente', motivo: 'notificacion_no_disponible' };
  }
  switch (resultado.correo?.estado_envio) {
    case 'enviado':
      return { accion: 'enviado', motivo: 'enviado' };
    case 'fallido':
      return { accion: 'fallido', motivo: 'rechazo_destinatario' };
    case 'pendiente':
      return { accion: 'pendiente', motivo: 'smtp_pendiente' };
    default:
      return { accion: 'pendiente', motivo: 'resultado_desconocido' };
  }
};

return $input.all().map((item, indice) => {
  const reserva = reservas[item.pairedItem?.item ?? indice]?.json?.body ?? {};
  return {
    json: {
      ...clasificar(item.json ?? {}),
      id_expediente: reserva.id_expediente ?? null,
      id_notificacion: reserva.id_notificacion ?? null,
    },
    pairedItem: { item: indice },
  };
});

// Rama de error de «Reservar aviso de evaluación» en la rama evaluaciones de agendamiento (HU0009-1.0 y HU0009-2.0, C2 y
// C41-4): un aviso que falla no frena a los demás del barrido, y este nodo prepara el registro del fallo. Emite solo los
// identificadores que admite POST /internal/errores-flujo: el flujo, el nodo y el id de esta ejecución. NO lee el ítem de
// entrada: trae el mensaje del error o el asunto y el cuerpo del aviso (C11).
// Un ítem de salida por cada aviso que falló.
const id = String($execution?.id ?? '');
const id_ejecucion = /^[0-9A-Za-z-]{1,40}$/.test(id) ? id : 'sin-id';

return $input.all().map((_item, indice) => ({
  json: { flujo: 'agendamiento', nodo: 'Reservar aviso de evaluación', id_ejecucion },
  pairedItem: { item: indice },
}));

// Rama de error de «Enviar aviso de evaluación» en la rama evaluaciones de agendamiento (HU0009-1.0 y HU0009-2.0, C2 y
// C41-4): un aviso que falla no frena a los demás del barrido, y este nodo prepara el registro del fallo. Emite solo los
// identificadores que admite POST /internal/errores-flujo: el flujo, el nodo y el id de esta ejecución. NO lee el ítem de
// entrada: trae el mensaje del error o el asunto y el cuerpo del aviso (C11).
// Un ítem de salida por cada aviso que falló.
const id = String($execution?.id ?? '');
const id_ejecucion = /^[0-9A-Za-z-]{1,40}$/.test(id) ? id : 'sin-id';

return $input.all().map((_item, indice) => ({
  json: { flujo: 'agendamiento', nodo: 'Enviar aviso de evaluación', id_ejecucion },
  pairedItem: { item: indice },
}));
